-- Niveles iniciales B / PD / T para todos los productos (30-sep-2026).
-- Pedido del dueño: «ponle una base y tope promedio de supermercado del tamaño de una tienda grande, minisupermercado».
--
-- Cómo se calculan (unidades; empaque = 1 en todo el catálogo):
--   1. Punto de partida por categoría (minisúper de barrio, visita semanal del proveedor).
--   2. Ajuste por precio: lo barato rota más y se tiene en más cantidad; lo caro, en menos.
--        ≤ $1.500 ×2 · ≤ $5.000 ×1 · ≤ $15.000 ×0,6 · > $15.000 ×0,35
--   3. Ajuste por rotación real, con el Excel de ventas del 16 al 23 de sept (652 productos vendidos):
--        S = unidades por semana.  B ≥ ⌈S/2⌉ (media semana de colchón) · PD ≥ B + ⌈S⌉ (una semana de venta)
--        · T ≥ PD + ⌈S/2⌉.
--   4. Orden obligatorio 0 < B < PD < T: PD ≥ B + 1 y T ≥ PD + 1.
-- Solo se llenan los productos que aún no tienen niveles: no pisa lo que el dueño ya haya puesto.

create temporary table category_levels (category text primary key, base integer, tope integer) on commit drop;

create temporary table weekly_rotation (barcode text primary key, weekly_units numeric) on commit drop;

with levels as (
  select
    p.id as product_id,
    greatest(1, round(coalesce(cl.base, 3) * price_factor.value)::integer) as category_base,
    greatest(3, round(coalesce(cl.tope, 10) * price_factor.value)::integer) as category_tope,
    coalesce(wr.weekly_units, 0) as weekly
  from products p
  join product_settings ps on ps.product_id = p.id
  left join category_levels cl on cl.category = p.category
  left join weekly_rotation wr on wr.barcode = p.barcode and wr.barcode is not null
  cross join lateral (
    select case
      when p.sale_price <= 1500 then 2.0
      when p.sale_price <= 5000 then 1.0
      when p.sale_price <= 15000 then 0.6
      else 0.35
    end as value
  ) as price_factor
  where ps.min_stock_units is null and ps.reorder_point_units is null and ps.max_stock_units is null
),
base_level as (
  select product_id, category_tope, weekly,
    greatest(category_base, ceil(weekly / 2)::integer) as base
  from levels
),
reorder_level as (
  select product_id, category_tope, weekly, base,
    greatest(base + 1, round((base + category_tope) / 2.0)::integer, base + ceil(weekly)::integer) as reorder_point
  from base_level
)
update product_settings ps
set min_stock_units = rl.base,
    reorder_point_units = rl.reorder_point,
    max_stock_units = greatest(rl.reorder_point + 1, rl.category_tope, rl.reorder_point + ceil(rl.weekly / 2)::integer),
    updated_at = now()
from reorder_level rl
where ps.product_id = rl.product_id;
